## SwiftUI Expandable Lists Information

For your SwiftUI training handout on expandable lists, the primary API you'll want to use is **`DisclosureGroup`**. This is SwiftUI's built-in component for creating expandable/collapsible content sections, often used within lists.

### Key Components:

1. **`DisclosureGroup`** - The main container for expandable content
2. **`DisclosureGroupStyle`** - For customizing the appearance
3. **`AutomaticDisclosureGroupStyle`** - The default style

### Basic Example Code:

Here's a simple example of how to use `DisclosureGroup` in a list:

```swift
import SwiftUI

struct ContentView: View {
    @State private var isExpanded = false

    var body: some View {
        List {
            DisclosureGroup("Settings", isExpanded: $isExpanded) {
                Text("Notification Settings")
                Text("Privacy Settings")
                Text("Account Settings")
            }

            DisclosureGroup("Help & Support") {
                Text("FAQ")
                Text("Contact Support")
                Text("Documentation")
            }
        }
    }
}
```

### Nested Disclosure Groups Example:

```swift
struct NestedDisclosureView: View {
    var body: some View {
        List {
            DisclosureGroup("Personal Information") {
                DisclosureGroup("Contact Details") {
                    Text("Email: user@example.com")
                    Text("Phone: (123) 456-7890")
                }

                DisclosureGroup("Address") {
                    Text("123 Main Street")
                    Text("City, State 12345")
                }
            }
        }
    }
}
```

### Using with Data Models:

```swift
struct Category: Identifiable {
    let id = UUID()
    let name: String
    let items: [String]
}

struct ExpandableListView: View {
    let categories = [
        Category(name: "Fruits", items: ["Apple", "Banana", "Orange"]),
        Category(name: "Vegetables", items: ["Carrot", "Broccoli", "Spinach"]),
        Category(name: "Dairy", items: ["Milk", "Cheese", "Yogurt"])
    ]

    var body: some View {
        List(categories) { category in
            DisclosureGroup(category.name) {
                ForEach(category.items, id: \.self) { item in
                    Text(item)
                        .padding(.leading)
                }
            }
        }
    }
}
```

### Custom Styling:

```swift
struct CustomDisclosureStyle: DisclosureGroupStyle {
    func makeBody(configuration: Configuration) -> some View {
        VStack {
            HStack {
                configuration.label
                Spacer()
                Image(systemName: configuration.isExpanded ? "chevron.down" : "chevron.right")
            }
            .contentShape(Rectangle())
            .onTapGesture {
                withAnimation {
                    configuration.isExpanded.toggle()
                }
            }

            if configuration.isExpanded {
                configuration.content
                    .padding(.leading)
            }
        }
    }
}
```

