Create `src/components/layout/Layout.tsx`:
```tsx
import React from 'react';
import { Outlet } from 'react-router-dom';
import Sidebar from './Sidebar';
import Header from './Header';

const Layout: React.FC = () => {
  return (
    <div className="flex h-screen bg-gray-50">
      <Sidebar />
      <div className="flex-1 flex flex-col overflow-hidden">
        <Header />
        <main className="flex-1 overflow-y-auto p-6">
          <Outlet />
        </main>
      </div>
    </div>
  );
};

export default Layout;
```

### 5. **Report Viewer Integration Options**

#### Option A: Using Telerik Reporting (Commercial)
If you have Telerik license:
```bash
npm install @progress/telerik-reporting-react
```

Create `src/components/reports/ReportViewer.tsx`:
```tsx
import React, { useEffect } from 'react';
import { TelerikReportViewer } from '@progress/telerik-reporting-react';

interface ReportViewerProps {
  reportUrl: string;
  serviceUrl: string;
}

const ReportViewer: React.FC<ReportViewerProps> = ({ reportUrl, serviceUrl }) => {
  return (
    <div className="h-full w-full">
      <TelerikReportViewer
        reportSource={{
          report: reportUrl,
        }}
        serviceUrl={serviceUrl}
        viewerContainerStyle={{ height: '800px', width: '100%' }}
      />
    </div>
  );
};

export default ReportViewer;
```

#### Option B: Using Open Source Alternatives

1. **For PDF reports:**
```bash
npm install react-pdf
```

2. **For embedded iframe reports:**
```tsx
import React from 'react';

interface EmbeddedReportProps {
  reportUrl: string;
  title: string;
}

const EmbeddedReport: React.FC<EmbeddedReportProps> = ({ reportUrl, title }) => {
  return (
    <div className="w-full h-[600px] border rounded-lg shadow-sm">
      <div className="p-4 border-b bg-gray-50">
        <h3 className="font-semibold text-gray-700">{title}</h3>
      </div>
      <iframe
        src={reportUrl}
        className="w-full h-[calc(600px-60px)]"
        title={title}
        frameBorder="0"
      />
    </div>
  );
};

export default EmbeddedReport;
```

### 6. **Dashboard Components**

Create `src/components/dashboard/SalesMetrics.tsx`:
```tsx
import React from 'react';
import { TrendingUp, TrendingDown, DollarSign, Users } from 'lucide-react';

const SalesMetrics: React.FC = () => {
  const metrics = [
    {
      title: 'Total Revenue',
      value: '$124,580',
      change: '+12.5%',
      trend: 'up',
      icon: DollarSign,
      color: 'bg-blue-500',
    },
    {
      title: 'New Customers',
      value: '324',
      change: '+8.2%',
      trend: 'up',
      icon: Users,
      color: 'bg-green-500',
    },
    {
      title: 'Conversion Rate',
      value: '3.24%',
      change: '-0.8%',
      trend: 'down',
      icon: TrendingUp,
      color: 'bg-purple-500',
    },
    {
      title: 'Avg. Order Value',
      value: '$142.50',
      change: '+5.3%',
      trend: 'up',
      icon: TrendingUp,
      color: 'bg-orange-500',
    },
  ];

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
      {metrics.map((metric, index) => (
        <div key={index} className="bg-white p-6 rounded-lg shadow-sm border">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-500">{metric.title}</p>
              <p className="text-2xl font-bold mt-2">{metric.value}</p>
              <div className="flex items-center mt-2">
                {metric.trend === 'up' ? (
                  <TrendingUp className="w-4 h-4 text-green-500 mr-1" />
                ) : (
                  <TrendingDown className="w-4 h-4 text-red-500 mr-1" />
                )}
                <span className={`text-sm ${metric.trend === 'up' ? 'text-green-600' : 'text-red-600'}`}>
                  {metric.change}
                </span>
                <span className="text-sm text-gray-500 ml-2">from last month</span>
              </div>
            </div>
            <div className={`${metric.color} p-3 rounded-full`}>
              <metric.icon className="w-6 h-6 text-white" />
            </div>
          </div>
        </div>
      ))}
    </div>
  );
};

export default SalesMetrics;
```

### 7. **App Configuration**

Update `src/App.tsx`:
```tsx
import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Layout from './components/layout/Layout';
import Dashboard from './pages/Dashboard';
import Reports from './pages/Reports';
import Analytics from './pages/Analytics';
import './App.css';

function App() {
  return (
    <Router>
      <Routes>
        <Route path="/" element={<Layout />}>
          <Route index element={<Dashboard />} />
          <Route path="reports" element={<Reports />} />
          <Route path="analytics" element={<Analytics />} />
        </Route>
      </Routes>
    </Router>
  );
}

export default App;
```

### 8. **API Service Layer**

Create `src/services/api.ts`:
```typescript
import axios from 'axios';

const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:3001/api';

const api = axios.create({
  baseURL: API_BASE_URL,
  headers: {
    'Content-Type': 'application/json',
  },
});

// Sales data endpoints
export const salesApi = {
  getMetrics: () => api.get('/sales/metrics'),
  getRevenueData: (period: string) => api.get(`/sales/revenue?period=${period}`),
  getTopProducts: (limit: number = 10) => api.get(`/sales/top-products?limit=${limit}`),
  getReports: () => api.get('/reports'),
  getReport: (id: string) => api.get(`/reports/${id}`),
};

export default api;
```

### 9. **Package.json Scripts**
Add to your `package.json`:
```json
{
  "scripts": {
    "start": "react-scripts start",
    "build": "react-scripts build",
    "test": "react-scripts test",
    "eject": "react-scripts eject",
    "dev": "concurrently \"npm start\" \"npm run server\"",
    "server": "node server/index.js"
  }
}
```

### 10. **Next Steps**

1. **Install additional dependencies:**
```bash
npm install lucide-react react-table @tanstack/react-table
```

2. **Set up mock backend (optional):**
```bash
npm install json-server concurrently
```

3. **Create mock data file:**
```json
// db.json
{
  "sales": {
    "metrics": {...},
    "revenue": [...],
    "topProducts": [...]
  },
  "reports": [...]
}
```

4. **Add to .gitignore:**
```
node_modules/
build/
.env
*.log
```

### **Key Considerations for Reporting Integration:**

1. **Report Server Setup:** You'll need a backend service to serve reports (Telerik Reporting REST Service, custom API, or third-party service)

2. **Authentication:** Implement proper authentication for both the dashboard and report access

3. **Report Types:** Determine what types of reports you need (PDF, HTML, Excel exports)

4. **Performance:** Consider lazy loading for large reports and implement pagination for report lists

5. **Mobile Responsiveness:** Ensure the report viewer works well on different screen sizes

This setup gives you a modern React dashboard foundation with clean UI components and a structure ready for report viewer integration. You can choose between commercial solutions like Telerik or open-source alternatives based on your specific requirements and budget.

