                    <div class="paper-date">Submitted: February 15, 2026</div>
                    <div class="paper-links">
                        <a href="https://arxiv.org/abs/2602.18025" class="btn btn-primary">Abstract</a>
                        <a href="https://arxiv.org/pdf/2602.18025" class="btn btn-pdf">PDF</a>
                    </div>
                </div>
