        "options": "<template>\n    <DataTable :value=\"sales\" tableStyle=\"min-width: 50rem\">\n        <ColumnGroup type=\"header\">\n            <Row>\n                <Column header=\"Product\" :rowspan=\"3\" />\n                <Column header=\"Sale Rate\" :colspan=\"4\" />\n            </Row>\n            <Row>\n                <Column header=\"Sales\" :colspan=\"2\" />\n                <Column header=\"Profits\" :colspan=\"2\" />\n            </Row>\n            <Row>\n                <Column header=\"Last Year\" sortable field=\"lastYearSale\"/>\n                <Column header=\"This Year\" sortable field=\"thisYearSale\"/>\n                <Column header=\"Last Year\" sortable field=\"lastYearProfit\"/>\n                <Column header=\"This Year\" sortable field=\"thisYearProfit\"/>\n            </Row>\n        </ColumnGroup>\n        <Column field=\"product\" />\n        <Column field=\"lastYearSale\">\n            <template #body=\"slotProps\">\n                {{slotProps.data.lastYearSale}}%\n            </template>\n        </Column>\n        <Column field=\"thisYearSale\">\n            <template #body=\"slotProps\">\n                {{slotProps.data.thisYearSale}}%\n            </template>\n        </Column>\n        <Column field=\"lastYearProfit\">\n            <template #body=\"slotProps\">\n                {{formatCurrency(slotProps.data.lastYearProfit)}}\n            </template>\n        </Column>\n        <Column field=\"thisYearProfit\">\n            <template #body=\"slotProps\">\n                {{formatCurrency(slotProps.data.thisYearProfit)}}\n            </template>\n        </Column>\n        <ColumnGroup type=\"footer\">\n            <Row>\n                <Column footer=\"Totals:\" :colspan=\"3\" footerStyle=\"text-align:right\"/>\n                <Column :footer=\"lastYearTotal\" />\n                <Column :footer=\"thisYearTotal\" />\n            </Row>\n        </ColumnGroup>\n    </DataTable>\n</template>\n\n<script>\nexport default {\n    data() {\n        return {\n            sales: null\n        }\n    },\n    created() {\n        this.sales = [\n            {product: 'Bamboo Watch', lastYearSale: 51, thisYearSale: 40, lastYearProfit: 54406, thisYearProfit: 43342},\n            {product: 'Black Watch', lastYearSale: 83, thisYearSale: 9, lastYearProfit: 423132, thisYearProfit: 312122},\n            {product: 'Blue Band', lastYearSale: 38, thisYearSale: 5, lastYearProfit: 12321, thisYearProfit: 8500},\n            {product: 'Blue T-Shirt', lastYearSale: 49, thisYearSale: 22, lastYearProfit: 745232, thisYearProfit: 65323},\n            {product: 'Brown Purse', lastYearSale: 17, thisYearSale: 79, lastYearProfit: 643242, thisYearProfit: 500332},\n            {product: 'Chakra Bracelet', lastYearSale: 52, thisYearSale:  65, lastYearProfit: 421132, thisYearProfit: 150005},\n            {product: 'Galaxy Earrings', lastYearSale: 82, thisYearSale: 12, lastYearProfit: 131211, thisYearProfit: 100214},\n            {product: 'Game Controller', lastYearSale: 44, thisYearSale: 45, lastYearProfit: 66442, thisYearProfit: 53322},\n            {product: 'Gaming Set', lastYearSale: 90, thisYearSale: 56, lastYearProfit: 765442, thisYearProfit: 296232},\n            {product: 'Gold Phone Case', lastYearSale: 75, thisYearSale: 54, lastYearProfit: 21212, thisYearProfit: 12533}\n        ];\n    },\n    methods: {\n        formatCurrency(value) {\n            return value.toLocaleString('en-US', {style: 'currency', currency: 'USD'});\n        }\n    },\n    computed: {\n        lastYearTotal() {\n            let total = 0;\n            for(let sale of this.sales) {\n                total += sale.lastYearProfit;\n            }\n\n            return this.formatCurrency(total);\n        },\n        thisYearTotal() {\n            let total = 0;\n            for(let sale of this.sales) {\n                total += sale.thisYearProfit;\n            }\n\n            return this.formatCurrency(total);\n        }\n    }\n}\n<\\/script>",
        "composition": "<template>\n    <DataTable :value=\"sales\" tableStyle=\"min-width: 50rem\">\n        <ColumnGroup type=\"header\">\n            <Row>\n                <Column header=\"Product\" :rowspan=\"3\" />\n                <Column header=\"Sale Rate\" :colspan=\"4\" />\n            </Row>\n            <Row>\n                <Column header=\"Sales\" :colspan=\"2\" />\n                <Column header=\"Profits\" :colspan=\"2\" />\n            </Row>\n            <Row>\n                <Column header=\"Last Year\" sortable field=\"lastYearSale\"/>\n                <Column header=\"This Year\" sortable field=\"thisYearSale\"/>\n                <Column header=\"Last Year\" sortable field=\"lastYearProfit\"/>\n                <Column header=\"This Year\" sortable field=\"thisYearProfit\"/>\n            </Row>\n        </ColumnGroup>\n        <Column field=\"product\" />\n        <Column field=\"lastYearSale\">\n            <template #body=\"slotProps\">\n                {{slotProps.data.lastYearSale}}%\n            </template>\n        </Column>\n        <Column field=\"thisYearSale\">\n            <template #body=\"slotProps\">\n                {{slotProps.data.thisYearSale}}%\n            </template>\n        </Column>\n        <Column field=\"lastYearProfit\">\n            <template #body=\"slotProps\">\n                {{formatCurrency(slotProps.data.lastYearProfit)}}\n            </template>\n        </Column>\n        <Column field=\"thisYearProfit\">\n            <template #body=\"slotProps\">\n                {{formatCurrency(slotProps.data.thisYearProfit)}}\n            </template>\n        </Column>\n        <ColumnGroup type=\"footer\">\n            <Row>\n                <Column footer=\"Totals:\" :colspan=\"3\" footerStyle=\"text-align:right\"/>\n                <Column :footer=\"lastYearTotal\" />\n                <Column :footer=\"thisYearTotal\" />\n            </Row>\n        </ColumnGroup>\n    </DataTable>\n</template>\n\n<script setup>\nimport { ref, computed } from 'vue';\n\nconst sales = ref([\n    {product: 'Bamboo Watch', lastYearSale: 51, thisYearSale: 40, lastYearProfit: 54406, thisYearProfit: 43342},\n    {product: 'Black Watch', lastYearSale: 83, thisYearSale: 9, lastYearProfit: 423132, thisYearProfit: 312122},\n    {product: 'Blue Band', lastYearSale: 38, thisYearSale: 5, lastYearProfit: 12321, thisYearProfit: 8500},\n    {product: 'Blue T-Shirt', lastYearSale: 49, thisYearSale: 22, lastYearProfit: 745232, thisYearProfit: 65323},\n    {product: 'Brown Purse', lastYearSale: 17, thisYearSale: 79, lastYearProfit: 643242, thisYearProfit: 500332},\n    {product: 'Chakra Bracelet', lastYearSale: 52, thisYearSale:  65, lastYearProfit: 421132, thisYearProfit: 150005},\n    {product: 'Galaxy Earrings', lastYearSale: 82, thisYearSale: 12, lastYearProfit: 131211, thisYearProfit: 100214},\n    {product: 'Game Controller', lastYearSale: 44, thisYearSale: 45, lastYearProfit: 66442, thisYearProfit: 53322},\n    {product: 'Gaming Set', lastYearSale: 90, thisYearSale: 56, lastYearProfit: 765442, thisYearProfit: 296232},\n    {product: 'Gold Phone Case', lastYearSale: 75, thisYearSale: 54, lastYearProfit: 21212, thisYearProfit: 12533}\n]);\n\nconst formatCurrency = (value) => {\n    return value.toLocaleString('en-US', {style: 'currency', currency: 'USD'});\n};\n\nconst lastYearTotal = computed(() => {\n    let total = 0;\n    for(let sale of sales.value) {\n        total += sale.lastYearProfit;\n    }\n\n    return formatCurrency(total);\n});\n\nconst thisYearTotal = computed(() => {\n    let total = 0;\n    for(let sale of sales.value) {\n        total += sale.thisYearProfit;\n    }\n\n    return formatCurrency(total);\n});\n\n<\\/script>"
