// Example function to fetch IP details
async function fetchIPDetails(ipAddress) {
  try {
    const response = await ip_get_details({
      ipAddress: ipAddress,
      outputFormat: 'json'
    });

    // Parse the response and map to your data structure
    return {
      ip: response.query,
      country: response.country,
      city: response.city,
      region: response.regionName,
      isp: response.isp,
      countryCode: response.countryCode
    };
  } catch (error) {
    console.error(`Failed to fetch details for ${ipAddress}:`, error);
    return null;
  }
}

// Usage in your component
const loadIPData = async (ipList) => {
  const results = [];
  for (const ip of ipList) {
    const details = await fetchIPDetails(ip);
    if (details) {
      results.push({
        id: results.length + 1,
        ...details
      });
    }
  }
  ipLocations.value = results;
};
```

