      setCpuUsage(prev => {
        const change = Math.random() * 10 - 5;
        return Math.max(0, Math.min(100, prev + change));
      });
      setMemoryUsage(prev => {
        const change = Math.random() * 8 - 4;
        return Math.max(0, Math.min(100, prev + change));
      });
    }, 3000);

    return () => clearInterval(interval);
  }, []);

  return (
    <Row gutter={16}>
      <Col span={12}>
        <Card title="CPU Usage" size="small">
