  } catch (error) {
    console.error('Error loading Google Maps:', error);
    // Show user-friendly error message
  }
});

async function loadNearbyStores() {
  // Example: Fetch stores from your backend or use Places API
  const { PlacesService } = await google.maps.importLibrary('places');
  const service = new PlacesService(map.value);

  const request = {
    location: map.value.getCenter(),
    radius: 5000, // 5km radius
    type: 'store',
    keyword: 'grocery' // Customize for your store type
  };

  service.nearbySearch(request, (results, status) => {
    if (status === google.maps.places.PlacesServiceStatus.OK) {
      stores.value = results.map(place => ({
        id: place.place_id,
        name: place.name,
        address: place.vicinity,
        location: place.geometry.location,
        rating: place.rating
      }));

      // Add markers for each store
      addStoreMarkers(stores.value);
    }
  });
}

function addStoreMarkers(storeList) {
  const { AdvancedMarkerElement } = google.maps.marker;

  markers.value.forEach(marker => marker.map = null); // Clear existing markers
  markers.value = [];

  storeList.forEach(store => {
    const marker = new AdvancedMarkerElement({
      position: store.location,
      map: map.value,
      title: store.name,
    });

    markers.value.push(marker);
  });
}

function centerMap(store) {
  map.value.setCenter(store.location);
  map.value.setZoom(16);
}

onUnmounted(() => {
  // Clean up markers
  markers.value.forEach(marker => marker.map = null);
});
</script>

