// components/ThemeToggle.tsx
import React, { useState, useEffect } from 'react';
import { useFeatureFlag } from '../hooks/useFeatureFlag';

interface ThemeToggleProps {
  className?: string;
}

export const ThemeToggle: React.FC<ThemeToggleProps> = ({ className }) => {
  const [isDarkMode, setIsDarkMode] = useState(false);
  const { isEnabled: isDarkModeFeatureEnabled } = useFeatureFlag('dark_mode_toggle');

  // Check for saved theme or system preference
  useEffect(() => {
    if (!isDarkModeFeatureEnabled) return;

    const savedTheme = localStorage.getItem('theme');
    const systemPrefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;

    if (savedTheme === 'dark' || (!savedTheme && systemPrefersDark)) {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }
  }, [isDarkModeFeatureEnabled]);

  const toggleTheme = () => {
    if (!isDarkModeFeatureEnabled) return;

    const newIsDarkMode = !isDarkMode;
    setIsDarkMode(newIsDarkMode);

    if (newIsDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  };

  if (!isDarkModeFeatureEnabled) {
    return null; // Hide toggle if feature flag is off
  }

  return (
    <button
      onClick={toggleTheme}
      className={`theme-toggle ${className || ''}`}
      aria-label={isDarkMode ? 'Switch to light mode' : 'Switch to dark mode'}
    >
      <span className="theme-toggle-icon">
        {isDarkMode ? '☀️' : '🌙'}
      </span>
      <span className="theme-toggle-text">
        {isDarkMode ? 'Light Mode' : 'Dark Mode'}
      </span>
    </button>
  );
};
```

