// hooks/useFeatureFlag.ts
import { useState, useEffect } from 'react';

interface FeatureFlag {
  isEnabled: boolean;
  isLoading: boolean;
}

export const useFeatureFlag = (flagKey: string): FeatureFlag => {
  const [isEnabled, setIsEnabled] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const checkFeatureFlag = async () => {
      try {
        // In production, this would call your feature flag service
        // For now, we'll use localStorage for gradual rollout simulation
        const savedFlag = localStorage.getItem(`feature_flag_${flagKey}`);

        if (savedFlag !== null) {
          setIsEnabled(savedFlag === 'true');
        } else {
          // Default rollout logic - 0% initially
          // You can adjust this percentage for gradual rollout
          const rolloutPercentage = 0; // Start with 0%
          const isUserInRollout = Math.random() * 100 < rolloutPercentage;
          setIsEnabled(isUserInRollout);

          // Save for consistency
          localStorage.setItem(`feature_flag_${flagKey}`, isUserInRollout.toString());
        }
      } catch (error) {
        console.error('Error checking feature flag:', error);
        setIsEnabled(false);
      } finally {
        setIsLoading(false);
      }
    };

    checkFeatureFlag();
  }, [flagKey]);

  return { isEnabled, isLoading };
};
```

