```

## 3. TypeScript Validation Class

For frontend validation before sending to API, here's a robust TypeScript class using `class-validator`:

```typescript
// UserData.ts
import {
  IsString,
  IsEmail,
  MinLength,
  MaxLength,
  IsInt,
  Min,
  Max,
  Matches,
  IsIn,
  IsBoolean,
  IsOptional,
  ValidateIf,
  validateSync,
  ValidationError
} from 'class-validator';
import { Type, plainToClass } from 'class-transformer';

export class UserData {
  @IsString({ message: 'Username must be a string' })
  @MinLength(3, { message: 'Username must be at least 3 characters' })
  @MaxLength(20, { message: 'Username cannot exceed 20 characters' })
  @Matches(/^[a-zA-Z0-9_]+$/, { 
    message: 'Username can only contain letters, numbers, and underscores' 
  })
  username!: string;

  @IsEmail({}, { message: 'Invalid email address' })
  email!: string;

  @IsString({ message: 'Password must be a string' })
  @MinLength(8, { message: 'Password must be at least 8 characters' })
  @MaxLength(100, { message: 'Password cannot exceed 100 characters' })
  @Matches(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d).+$/, {
    message: 'Password must contain at least one uppercase letter, one lowercase letter, and one number'
  })
  password!: string;

  @IsInt({ message: 'Age must be an integer' })
  @Min(18, { message: 'User must be at least 18 years old' })
  @Max(100, { message: 'Age cannot exceed 100' })
  @Type(() => Number)
  age!: number;

  @IsString({ message: 'Phone must be a string' })
  @Matches(/^[\d\s\-()+]+$/, { message: 'Invalid phone number format' })
  phone!: string;

  @IsIn(['admin', 'user', 'moderator'], { 
    message: 'Role must be one of: admin, user, moderator' 
  })
  role!: 'admin' | 'user' | 'moderator';

  @IsString({ message: 'Department must be a string' })
  @IsIn(['engineering', 'marketing', 'sales', 'hr', 'finance'], {
    message: 'Invalid department selected'
  })
  department!: string;

  @IsBoolean({ message: 'isActive must be a boolean' })
  isActive!: boolean;

  @IsString({ message: 'Bio must be a string' })
  @MaxLength(500, { message: 'Bio cannot exceed 500 characters' })
  @IsOptional()
  bio?: string;

  // Validation methods
  validate(): ValidationError[] {
    return validateSync(this);
  }

  isValid(): boolean {
    return this.validate().length === 0;
  }

  getErrorMessages(): string[] {
    const errors = this.validate();
    const messages: string[] = [];

    errors.forEach(error => {
      if (error.constraints) {
        messages.push(...Object.values(error.constraints));
      }
    });

    return messages;
  }

  // Static constructor from plain object
  static create(data: Partial<UserData>): UserData {
    const instance = plainToClass(UserData, data);
    return instance;
  }

  // Serialize for API
  toJSON(): Record<string, any> {
    return {
      username: this.username,
      email: this.email,
      password: this.password,
      age: this.age,
      phone: this.phone,
      role: this.role,
      department: this.department,
      isActive: this.isActive,
      bio: this.bio
    };
  }
}

// Usage example in React component:
