{"code": "// UserFormData.ts - TypeScript class with validation decorators
// Using class-validator decorators for validation

import { 
  IsString, 
  IsEmail, 
  MinLength, 
  MaxLength, 
  IsInt, 
  Min, 
  Max, 
  IsPhoneNumber, 
  IsIn, 
  IsBoolean,
  IsOptional,
  ValidateIf,
  Equals,
  validateSync,
  ValidationError
} from 'class-validator';
import { plainToClass } from 'class-transformer';

export class UserFormData {
  @IsString({ message: 'Username must be a string' })
  @MinLength(3, { message: 'Username must be at least 3 characters long' })
  @MaxLength(20, { message: 'Username cannot exceed 20 characters' })
  username: string = '';

  @IsEmail({}, { message: 'Invalid email address' })
  email: string = '';

  @IsString({ message: 'Password must be a string' })
  @MinLength(8, { message: 'Password must be at least 8 characters long' })
  @MaxLength(100, { message: 'Password cannot exceed 100 characters' })
  password: string = '';

  @IsInt({ message: 'Age must be an integer' })
  @Min(18, { message: 'Age must be at least 18' })
  @Max(100, { message: 'Age cannot exceed 100' })
  age: number = 18;

  @IsPhoneNumber(null, { message: 'Invalid phone number format' })
  @IsOptional()
  phone?: string;

  @IsIn(['admin', 'user', 'moderator'], { message: 'Role must be one of: admin, user, moderator' })
  role: 'admin' | 'user' | 'moderator' = 'user';

  @IsBoolean({ message: 'isActive must be a boolean' })
  isActive: boolean = true;

  @IsString({ message: 'Bio must be a string' })
  @MaxLength(500, { message: 'Bio cannot exceed 500 characters' })
  @IsOptional()
  bio?: string;

  // Validation method
  validate(): ValidationError[] {
    const errors = validateSync(this);
    return errors;
  }

  // Check if valid
  isValid(): boolean {
    return this.validate().length === 0;
  }

  // Get error messages
  getErrorMessages(): string[] {
    const errors = this.validate();
    const messages: string[] = [];

    errors.forEach(error => {
      if (error.constraints) {
        Object.values(error.constraints).forEach(message => {
          messages.push(message);
        });
      }
    });

    return messages;
  }

  // Create instance from plain object
  static fromPlain(obj: any): UserFormData {
    return plainToClass(UserFormData, obj);
  }

  // Convert to plain object for API submission
  toPlain(): Record<string, any> {
    return {
      username: this.username,
      email: this.email,
      password: this.password,
      age: this.age,
      phone: this.phone,
      role: this.role,
      isActive: this.isActive,
      bio: this.bio
    };
  }
}

