  namespace: 'admin-dashboard',
  flags: {
    'dark-mode-toggle': {
      name: 'Dark Mode Toggle',
      type: 'boolean',
      enabled: true,
      description: 'Controls visibility of dark mode toggle in admin dashboard'
    }
  }
};
```

