Here's a React component that checks the feature flag and renders the toggle only when enabled:

```jsx
import React, { useState, useEffect } from 'react';
import { useFeatureFlag } from './featureFlagService'; // Your feature flag hook

const DarkModeToggle = () => {
  const [isDarkMode, setIsDarkMode] = useState(false);
  const isToggleEnabled = useFeatureFlag('admin-dashboard', 'dark-mode-toggle');

  useEffect(() => {
    // Check for saved preference or system preference
    const savedTheme = localStorage.getItem('theme');
    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;

    if (savedTheme === 'dark' || (!savedTheme && prefersDark)) {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }
  }, []);

  const toggleDarkMode = () => {
    const newDarkMode = !isDarkMode;
    setIsDarkMode(newDarkMode);

    if (newDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  };

  if (!isToggleEnabled) {
    return null; // Don't render anything if flag is disabled
  }

  return (
    <div className="dark-mode-toggle">
      <button
        onClick={toggleDarkMode}
        className="flex items-center justify-center w-10 h-10 rounded-full bg-gray-200 dark:bg-gray-800 hover:bg-gray-300 dark:hover:bg-gray-700 transition-colors"
