```

## Feature Flag Service Hook

Create a simple hook to check feature flags:

```jsx
// featureFlagService.js
import { useEffect, useState } from 'react';

export const useFeatureFlag = (namespace, flagKey) => {
  const [isEnabled, setIsEnabled] = useState(false);

  useEffect(() => {
    // Replace with your actual feature flag API call
    const checkFlag = async () => {
      try {
        const response = await fetch(`/api/feature-flags/${namespace}/${flagKey}`);
        const data = await response.json();
        setIsEnabled(data.enabled);
      } catch (error) {
        console.error('Error checking feature flag:', error);
