      map.setZoom(zoom);
    }
  }, [map, center, zoom]);

  return (
    <IressContainer fluid className={`map-container-wrapper ${className}`}>
      <IressRow>
        <IressCol xs={24} sm={24} md={24} lg={24} xl={24}>
          <div className="map-header">
            <h3>Interactive Map</h3>
            {error && <div className="map-error">{error}</div>}
          </div>

          <div 
            ref={mapRef} 
            className="map-responsive-container"
            style={{ 
              height: typeof height === 'number' ? `${height}px` : height,
              minHeight: '300px', // Minimum height for mobile
              position: 'relative',
            }}
          >
            {isLoading && (
              <div className="map-loading">
                <div className="loading-spinner"></div>
                <p>Loading map...</p>
              </div>
            )}
          </div>

          <div className="map-footer">
            <small>Powered by Google Maps</small>
          </div>
        </IressCol>
      </IressRow>
    </IressContainer>
  );
};

export default MapContainer;
```

## 3. Responsive Sizing Strategies

### Option A: Fluid Container (Recommended)
```tsx
<IressContainer fluid>
  {/* Map content */}
</IressContainer>
```
- **Behavior**: Container spans 100% width of parent at all breakpoints
- **Use case**: Full-width maps, dashboard layouts

### Option B: Responsive Breakpoints
```tsx
<IressContainer>
  <IressRow gutter={{ xs: 16, sm: 20, md: 24, lg: 32, xl: 40 }}>
    <IressCol xs={24} sm={24} md={20} lg={18} xl={16}>
      {/* Map with responsive margins */}
    </IressCol>
  </IressRow>
</IressContainer>
```
- **Breakpoint widths**:
  - xs (0-575px): 100%
  - sm (576-767px): 520px max
  - md (768-1023px): 740px max
  - lg (1024-1199px): 960px max
  - xl (1200-1499px): 1160px max
  - xxl (1500+): 1160px max

