  {
    id: "store_001",
    name: "Downtown Flagship",
    address: "123 Main St, City, State",
    coordinates: { lat: 40.7128, lng: -74.0060 },
    placeId: "ChIJVSZzVR8FdkgRTyQkxxLQmVU", // Google Place ID
    inventoryApiEndpoint: "/api/stores/store_001/inventory"
  }
];

// Geocode addresses (one-time setup)
async function geocodeStores(stores) {
  const geocoder = new google.maps.Geocoder();
  for (const store of stores) {
    const response = await geocoder.geocode({ address: store.address });
    store.coordinates = response.results[0].geometry.location;
    store.placeId = response.results[0].place_id;
  }
}
```

**Pro Tip:** Use the [Find Place endpoint](https://developers.google.com/maps/documentation/places/web-service/search#FindPlaceRequests) to get Place IDs for existing stores.

