// Fetch inventory for all stores
async function loadStoresWithInventory() {
  // 1. Get store locations from your database
  const stores = await fetch('/api/stores').then(r => r.json());

  // 2. Fetch inventory for each store in parallel
  const storesWithInventory = await Promise.all(
    stores.map(async store => {
      try {
        // Call your product API for this store's inventory
        const inventory = await fetch(
          `/api/inventory?storeId=${store.id}&productIds=${selectedProductIds}`
        ).then(r => r.json());

        return {
          ...store,
          inventory,
          hasStock: inventory.some(item => item.quantity > 0),
          lowStock: inventory.some(item => item.quantity > 0 && item.quantity < 10)
        };
      } catch (error) {
        console.error(`Failed to load inventory for ${store.name}:`, error);
        return { ...store, inventory: [], hasStock: false };
      }
    })
  );

  return storesWithInventory;
}

// Real-time inventory updates (using WebSocket or polling)
function setupInventoryUpdates(map) {
  // Option 1: WebSocket for real-time updates
  const ws = new WebSocket('wss://your-api.com/inventory-updates');
  ws.onmessage = (event) => {
    const update = JSON.parse(event.data);
    updateStoreMarker(update.storeId, update.inventory);
  };

  // Option 2: Polling every 60 seconds
  setInterval(async () => {
    const updates = await fetch('/api/inventory/updates?since=' + lastUpdateTime);
    updates.forEach(update => updateStoreMarker(update.storeId, update.inventory));
  }, 60000);
}
```

### **Step 5: Add User Location & Search**
```javascript
// Place Autocomplete for address search
function initAutocomplete() {
  const input = document.getElementById("store-search");
  const autocomplete = new google.maps.places.Autocomplete(input, {
    types: ["address"],
    componentRestrictions: { country: "us" }
  });

  autocomplete.addListener("place_changed", () => {
    const place = autocomplete.getPlace();
    if (place.geometry) {
      map.setCenter(place.geometry.location);
      map.setZoom(14);
      updateNearbyStores(place.geometry.location);
    }
  });
}

// Geolocation for "Use My Location"
function getUserLocation() {
  if (navigator.geolocation) {
    navigator.geolocation.getCurrentPosition(
      (position) => {
        const userLocation = {
          lat: position.coords.latitude,
          lng: position.coords.longitude
        };
        map.setCenter(userLocation);
        updateNearbyStores(userLocation);
      },
      (error) => {
        console.error("Geolocation error:", error);
        // Fallback to IP-based geolocation
      }
    );
  }
}
```

### **Step 6: Calculate Distances & Travel Times**
```javascript
async function calculateDistances(userLocation, stores) {
  const { DistanceMatrixService } = await google.maps.importLibrary("routes");
  const service = new DistanceMatrixService();

  const origins = [userLocation];
  const destinations = stores.map(store => store.coordinates);

  return new Promise((resolve, reject) => {
    service.getDistanceMatrix(
      {
        origins,
        destinations,
        travelMode: google.maps.TravelMode.DRIVING,
        unitSystem: google.maps.UnitSystem.IMPERIAL,
      },
      (response, status) => {
        if (status === "OK") {
          stores.forEach((store, i) => {
            store.distance = response.rows[0].elements[i].distance;
            store.duration = response.rows[0].elements[i].duration;
          });
          resolve(stores);
        } else {
          reject(status);
        }
      }
    );
  });
}
```

### **Step 7: Display Store Details with Inventory**
```javascript
function showStoreDetails(store) {
  // Use Places UI Kit for cost-effective place details
  const detailsElement = document.getElementById("store-details");

  detailsElement.innerHTML = `
    <div class="store-card">
      <h3>${store.name}</h3>
      <p>${store.address}</p>
      <p>${store.distance?.text || ''} • ${store.duration?.text || ''}</p>

      <div class="inventory-section">
        <h4>Available Inventory</h4>
        ${store.inventory.length > 0 
          ? store.inventory.map(item => `
              <div class="inventory-item ${item.quantity < 5 ? 'low-stock' : ''}">
                <span>${item.productName}</span>
                <span>${item.quantity} in stock</span>
                ${item.quantity > 0 
                  ? `<button onclick="reserveProduct('${item.productId}', '${store.id}')">
                       Reserve for Pickup
                     </button>`
                  : '<span class="out-of-stock">Out of Stock</span>'
                }
              </div>
            `).join('')
          : '<p>No inventory data available</p>'
        }
      </div>

      <button onclick="getDirections('${store.placeId}')">
        Get Directions
      </button>
      <button onclick="checkoutForPickup('${store.id}')">
        Buy Online, Pickup In Store
      </button>
    </div>
  `;
}
```

