async function getDirections(placeId) {
  // Use Maps URLs for cost-effective directions
  const url = `https://www.google.com/maps/dir/?api=1&destination_place_id=${placeId}&destination=Store+Location`;

  // Open in new tab or embed directions
  window.open(url, '_blank');

  // Alternative: Embed directions in your site
