[TextContent(type='text', text='### Managing Cookies in Express.js with `res.cookie()` and `res.clearCookie()`

Source: https://context7.com/expressjs/express/llms.txt

This example illustrates how to set and clear HTTP cookies in an Express.js application. It covers setting simple cookies, cookies with various options (e.g., `maxAge`, `httpOnly`, `secure`, `sameSite`), signed cookies for tamper detection, and JSON cookies. It also shows how to read cookies from the request object.

```javascript
const express = require('express');
const cookieParser = require('cookie-parser');
const app = express();

app.use(cookieParser('my-secret-key'));
app.use(express.urlencoded({ extended: false }));

// Set a simple cookie
app.get('/set-cookie', (req, res) => {
  res.cookie('theme', 'dark');
  res.send('Cookie set!');
});

// Set cookie with options
app.get('/login', (req, res) => {
  res.cookie('session', 'abc123', {
    maxAge: 900000,        // 15 minutes in ms
    httpOnly: true,        // Not accessible via JavaScript
    secure: true,          // HTTPS only
    sameSite: 'strict'     // CSRF protection
  });
  res.send('Logged in!');
});

// Set signed cookie
app.get('/signed', (req, res) => {
  res.cookie('user', 'john', { signed: true });
  res.send('Signed cookie set!');
});

// Set JSON cookie
app.get('/prefs', (req, res) => {
  res.cookie('preferences', { theme: 'dark', lang: 'en' }, {
    maxAge: 86400000
  });
  res.send('Preferences saved!');
});

// Read cookies
app.get('/read', (req, res) => {
  res.json({
    cookies: req.cookies,
    signedCookies: req.signedCookies
  });
});

// Clear cookie
app.get('/logout', (req, res) => {
  res.clearCookie('session');
  res.redirect('/');
});

app.listen(3000);
```

