### Retrieve Request Headers and Client Information in Express.js

Source: https://context7.com/expressjs/express/llms.txt

This Express.js example demonstrates how to access request headers and client-specific information. It covers using `req.get()` for specific headers, `req.headers` for all headers, and properties like `req.ip`, `req.hostname`, `req.protocol`, and `req.method` to get details about the client and the request itself. It also shows how to enable `trust proxy` for accurate IP detection.

```javascript
const express = require('express');
const app = express();

// Enable trust proxy for accurate IP when behind proxy
app.set('trust proxy', true);

app.get('/info', (req, res) => {
  res.json({
    // Get specific header (case-insensitive)
    contentType: req.get('Content-Type'),
    userAgent: req.get('User-Agent'),
    authorization: req.get('Authorization'),

    // All headers
    headers: req.headers,

    // Request URL info
    protocol: req.protocol,      // 'http' or 'https'
    secure: req.secure,          // true if https
    hostname: req.hostname,      // Host without port
    host: req.host,              // Host with port
    path: req.path,              // URL path
    originalUrl: req.originalUrl,
    baseUrl: req.baseUrl,

    // Client IP (respects trust proxy setting)
    ip: req.ip,
    ips: req.ips,               // Array when trust proxy enabled

    // Subdomains
    subdomains: req.subdomains,

    // HTTP method and freshness
    method: req.method,
    fresh: req.fresh,
    stale: req.stale,
    xhr: req.xhr                 // true if X-Requested-With: XMLHttpRequest
  });
});

app.listen(3000);
// curl -H "Authorization: Bearer token123" http://localhost:3000/info
```

