[TextContent(type='text', text="### Node.js JWT Authentication and Refresh Token Flow

Source: https://context7.com/auth0/node-jsonwebtoken/llms.txt

Implements a full authentication flow using JWTs with Node.js and Express.js. It includes middleware for authenticating tokens, generating access and refresh tokens, handling token refresh requests, and role-based authorization. It uses an in-memory store for refresh tokens, which should be replaced with a persistent store like Redis or a database in production.

```javascript
const jwt = require('jsonwebtoken');
const express = require('express');
const app = express();

// Configuration
const ACCESS_TOKEN_SECRET = process.env.ACCESS_TOKEN_SECRET || 'access-secret';
const REFRESH_TOKEN_SECRET = process.env.REFRESH_TOKEN_SECRET || 'refresh-secret';
const ACCESS_TOKEN_EXPIRY = '15m';
const REFRESH_TOKEN_EXPIRY = '7d';

// In-memory store (use Redis or database in production)
const refreshTokenStore = new Set();

// Generate access and refresh tokens
function generateTokens(user) {
  const accessToken = jwt.sign(
    { userId: user.id, email: user.email, role: user.role },
    ACCESS_TOKEN_SECRET,
    { expiresIn: ACCESS_TOKEN_EXPIRY, issuer: 'my-app', audience: 'my-api' }
  );

  const refreshToken = jwt.sign(
    { userId: user.id, tokenType: 'refresh' },
    REFRESH_TOKEN_SECRET,
    { expiresIn: REFRESH_TOKEN_EXPIRY, issuer: 'my-app' }
  );

  return { accessToken, refreshToken };
}

// Authentication middleware
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, ACCESS_TOKEN_SECRET, { audience: 'my-api' }, (err, decoded) => {
    if (err) {
      if (err instanceof jwt.TokenExpiredError) {
        return res.status(401).json({ error: 'Token expired', code: 'TOKEN_EXPIRED' });
      }
      return res.status(403).json({ error: 'Invalid token' });
    }

    req.user = decoded;
    next();
  });
}

// Role-based authorization middleware
function authorize(...roles) {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Not authenticated' });
    }

    if (!roles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
}

// Login endpoint
app.post('/api/login', async (req, res) => {
  const { email, password } = req.body;

  // Validate credentials (example - implement your own logic)
  const user = { id: 12345, email, role: 'user' };

  const { accessToken, refreshToken } = generateTokens(user);
  refreshTokenStore.add(refreshToken);

  res.json({
    accessToken,
    refreshToken,
    expiresIn: ACCESS_TOKEN_EXPIRY,
    tokenType: 'Bearer'
  });
});

// Refresh token endpoint
app.post('/api/refresh', (req, res) => {
  const { refreshToken } = req.body;

  if (!refreshToken) {
    return res.status(401).json({ error: 'Refresh token required' });
  }

  if (!refreshTokenStore.has(refreshToken)) {
    return res.status(403).json({ error: 'Invalid refresh token' });
  }

  jwt.verify(refreshToken, REFRESH_TOKEN_SECRET, (err, decoded) => {
    if (err) {
      refreshTokenStore.delete(refreshToken);
      return res.status(403).json({ error: 'Refresh token expired or invalid' });
    }

    // Generate new access token
    const newAccessToken = jwt.sign(
      { userId: decoded.userId },
      ACCESS_TOKEN_SECRET,
      { expiresIn: ACCESS_TOKEN_EXPIRY, issuer: 'my-app', audience: 'my-api' }
    );

    res.json({
      accessToken: newAccessToken,
      expiresIn: ACCESS_TOKEN_EXPIRY,
      tokenType: 'Bearer'
    });
  });
});

// Logout endpoint
app.post('/api/logout', authenticateToken, (req, res) => {
  const { refreshToken } = req.body;
  if (refreshToken) {
    refreshTokenStore.delete(refreshToken);
  }
  res.json({ message: 'Logged out successfully' });
});

// Protected routes
app.get('/api/profile', authenticateToken, (req, res) => {
  res.json({
    userId: req.user.userId,
    email: req.user.email,
    role: req.user.role
  });
});

app.get('/api/admin', authenticateToken, authorize('admin'), (req, res) => {
  res.json({ message: 'Admin access granted', user: req.user });
});

// Error handling for async routes
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

app.get('/api/data', authenticateToken, asyncHandler(async (req, res) => {
  // Async operations with JWT-authenticated user
  const data = await fetchUserData(req.user.userId);
  res.json(data);
}));

// Token introspection endpoint
app.post('/api/token/introspect', (req, res) => {
  const { token } = req.body;

  try {
    const decoded = jwt.verify(token, ACCESS_TOKEN_SECRET);
    res.json({
      active: true,
      userId: decoded.userId,
      email: decoded.email,
      exp: decoded.exp,
      iat: decoded.iat
    });
  } catch (err) {
    res.json({ active: false });
  }
});

// Placeholder for fetchUserData (implement your actual data fetching logic)
