    {
      "title": "Exploring the impacts of low‐cost digital technologies on cognitive impairment",
      "authors": [
        {
          "given": "Arman",
          "family": "Hajikarim‐Hamedani",
          "name": "Arman Hajikarim‐Hamedani"
        },
